/**
 * The SRD item catalog (plan-uat2 §3.5), generated by `dnd2024:data` into
 * `data/dnd5e-2024/economy/items.json`: price, weight, type, and armor's AC, Dexterity cap,
 * Strength requirement and Stealth disadvantage. Only the shop, purse, carry summary and the
 * equip slots load it; it is not part of the game data or the sheet's first load.
 */

/** `[costCp, weightLb, type]`; armor and shields add `acBase, dexCap (null: no cap), strReq, stealth (0/1)`. */
export type CatalogRow =
  | readonly [number | null, number, string]
  | readonly [number | null, number, string, number, number | null, number, 0 | 1];
export type Catalog = Readonly<Record<string, CatalogRow>>;

export interface CatalogArmor {
  ac: number;
  dexCap: number | null;
  strReq: number;
  stealth: boolean;
}

export interface CatalogItem {
  ref: string;
  /** Null: the SRD gives no price (a trinket), so the shop does not sell it. */
  costCp: number | null;
  weight: number;
  /** The 5etools item type: `M`, `R`, `LA`, `MA`, `HA`, `S`, `G`, `A`, `SCF`, `P`, `SC`, … */
  type: string;
  armor?: CatalogArmor;
}

export function catalogItem(catalog: Catalog | null | undefined, ref: unknown): CatalogItem | undefined {
  if (!catalog || typeof ref !== "string" || !Object.hasOwn(catalog, ref)) return undefined;
  const row = catalog[ref];
  const [costCp, weight, type] = row;
  const item: CatalogItem = { ref, costCp, weight, type };
  if (row.length === 7) item.armor = { ac: row[3], dexCap: row[4], strReq: row[5], stealth: row[6] === 1 };
  return item;
}

/** The equipment slot an item fills (SRD p.92 "One at a Time"): body armor or a shield. */
export type Slot = "body" | "shield";

export function slotOf(item: CatalogItem | undefined): Slot | null {
  if (!item) return null;
  if (item.type === "S") return "shield";
  return item.type === "LA" || item.type === "MA" || item.type === "HA" ? "body" : null;
}

/** The sheet's `armorType` of body armor. */
export function armorCategory(item: CatalogItem | undefined): "light" | "medium" | "heavy" | null {
  switch (item?.type) {
    case "LA":
      return "light";
    case "MA":
      return "medium";
    case "HA":
      return "heavy";
    default:
      return null;
  }
}

export const SHOP_CATEGORIES = ["weapon", "armor", "tools", "gear", "ammo", "focus", "pack"] as const;
export type ShopCategory = (typeof SHOP_CATEGORIES)[number];

const CATEGORY_OF_TYPE: Readonly<Record<string, ShopCategory>> = {
  M: "weapon", R: "weapon",
  LA: "armor", MA: "armor", HA: "armor", S: "armor",
  AT: "tools", T: "tools", GS: "tools", INS: "tools",
  A: "ammo",
  SCF: "focus",
};

/** The shop chip an item lists under; the SRD's packs (`*-pack`, p.97) are 背包. */
export function shopCategory(item: CatalogItem): ShopCategory {
  if (/^item:[a-z-]+s-pack$/.test(item.ref)) return "pack";
  return CATEGORY_OF_TYPE[item.type] ?? "gear";
}

/** Weapons and armor take a +N (SRD p.210 Armor +1/+2/+3, p.243 Shield, p.253 Weapon). */
export function takesBonus(item: CatalogItem | undefined): boolean {
  return !!item && (CATEGORY_OF_TYPE[item.type] === "weapon" || CATEGORY_OF_TYPE[item.type] === "armor");
}

let loaded: Promise<Catalog> | null = null;

/** One load per session; a failed load is retried by the next call. */
export function loadCatalog(): Promise<Catalog> {
  if (!loaded) {
    const pending = import("@skald/system-dnd5e/data/dnd5e-2024/economy/items.json").then((module) => module.default as unknown as Catalog);
    loaded = pending;
    // Marked the way React's `use` reads a settled promise, so a later render does not suspend.
    void pending.then((value) => Object.assign(pending, { status: "fulfilled", value }), () => {});
    pending.catch(() => {
      if (loaded === pending) loaded = null;
    });
  }
  return loaded;
}
